. /etc/os-release
case " $ID $ID_LIKE " in
  *" debian "*)            echo "$ID: apt-get install -y tree" ;;
  *" rhel "*|*" fedora "*) echo "$ID: dnf install -y tree" ;;
  *" alpine "*)            echo "$ID: apk add tree" ;;
  *" arch "*)              echo "$ID: pacman -S --noconfirm tree" ;;
  *)                       echo "$ID: nieznana rodzina" ;;
esac

